// Lexical lookup for the syntax-tree tool, read from the installed Open English WordNet data.
// Only the compact POS buckets generated by scripts/dictionary-headwords.mjs are fetched, and
// only for the initial letters a sentence actually uses. The full sense buckets stay untouched.
export type WordNetPos = 'noun' | 'verb' | 'adjective' | 'adverb';

export type PosLookup = (word: string) => readonly (readonly [WordNetPos, number])[] | undefined;

const base = '/dictionary/oewn-2025/';
const parts: WordNetPos[] = ['noun', 'verb', 'adjective', 'adverb'];
const buckets = new Map<string, Promise<Record<string, number>>>();

function bucket(letter: string) {
  if (!buckets.has(letter)) buckets.set(letter, fetch(`${base}pos-${letter}.json`).then(async response => {
    if (!response.ok) { await response.body?.cancel().catch(() => {}); throw new Error('DICTIONARY_UNAVAILABLE'); }
    return response.json() as Promise<Record<string, number>>;
  }).catch(error => { buckets.delete(letter); throw error; }));
  return buckets.get(letter)!;
}

let forms: Promise<Record<string, string[]>> | undefined;
function inflections() {
  forms ??= fetch(`${base}forms.json`).then(async response => {
    if (!response.ok) { await response.body?.cancel().catch(() => {}); throw new Error('DICTIONARY_UNAVAILABLE'); }
    return response.json() as Promise<Record<string, string[]>>;
  }).catch(error => { forms = undefined; throw error; });
  return forms;
}

export function decodePos(value: number): Record<WordNetPos, number> {
  return { noun: value & 15, verb: (value >> 4) & 15, adjective: (value >> 8) & 15, adverb: (value >> 12) & 15 };
}

// Regular English inflections plus the WordNet irregular list, so "books" and "sat" reach a lemma.
// Stripping is deliberately conservative: short words such as "sat" or "this" must not become
// invented lemmas like "sa" or "thi".
//
// A suffix also constrains which readings the stem can lend. Stripping "-s" yields a noun or a
// verb, never an adjective, so "news" is not read through the adjective "new"; stripping "-ing"
// yields a verb, a noun or an adjective, so "heartbreaking" reaches the verb "heartbreak".
const suffixReadings: Record<string, WordNetPos[]> = {
  nounVerb: ['noun', 'verb'],
  verbNounAdjective: ['verb', 'noun', 'adjective'],
  verbAdjective: ['verb', 'adjective'],
  degree: ['adjective', 'adverb'],
};

export function lemmaReadings(word: string, forms: Record<string, string[]> = {}) {
  const term = word.normalize('NFKC').toLocaleLowerCase('en-US');
  const out: { candidate: string; allowed?: WordNetPos[] }[] = [];
  const seen = new Set<string>();
  const declared = Object.hasOwn(forms, term) ? forms[term] : [];
  for (const candidate of declared) if (candidate !== term && !seen.has(candidate)) { seen.add(candidate); out.push({ candidate }); }
  const add = (value: string, allowed?: WordNetPos[]) => {
    if (value.length > 1 && value !== term && !seen.has(value)) { seen.add(value); out.push({ candidate: value, allowed }); }
  };
  const nounVerb = suffixReadings.nounVerb;
  const verbNounAdjective = suffixReadings.verbNounAdjective;
  const verbAdjective = suffixReadings.verbAdjective;
  const degree = suffixReadings.degree;
  if (/ies$/.test(term) && term.length > 4) { add(`${term.slice(0, -3)}y`, nounVerb); add(term.slice(0, -3), nounVerb); }
  if (/ied$/.test(term) && term.length > 4) add(`${term.slice(0, -3)}y`, nounVerb);
  if (/(?:s|x|z|ch|sh)es$/.test(term) && term.length > 4) add(term.slice(0, -2), nounVerb);
  else if (/s$/.test(term) && !/(?:ss|us|is|ous)$/.test(term) && term.length > 3) add(term.slice(0, -1), nounVerb);
  if (/ing$/.test(term) && term.length > 4) {
    const stem = term.slice(0, -3);
    add(stem, verbNounAdjective); add(`${stem}e`, verbNounAdjective);
    if (stem.at(-1) === stem.at(-2)) add(stem.slice(0, -1), verbNounAdjective);
  }
  if (/ed$/.test(term) && term.length > 3) {
    const stem = term.slice(0, -2);
    add(stem, verbAdjective); add(`${stem}e`, verbAdjective);
    if (stem.at(-1) === stem.at(-2)) add(stem.slice(0, -1), verbAdjective);
  }
  const degreeSuffix = term.endsWith('est') ? 3 : term.endsWith('er') ? 2 : 0;
  if (degreeSuffix && term.length > degreeSuffix + 2) {
    const stem = term.slice(0, -degreeSuffix);
    add(stem, degree); add(`${stem}e`, degree);
    if (stem.endsWith('i')) add(`${stem.slice(0, -1)}y`, degree);
    if (stem.at(-1) === stem.at(-2)) add(stem.slice(0, -1), degree);
  }
  return out.slice(0, 12);
}

export function lemmaCandidates(word: string, forms: Record<string, string[]> = {}, part?: WordNetPos) {
  return lemmaReadings(word, forms).filter(reading => !part || !reading.allowed || reading.allowed.includes(part)).map(reading => reading.candidate);
}

export function resolvePos(word: string, bucketsByLetter: Map<string, Record<string, number>>, forms: Record<string, string[]> = {}): Record<WordNetPos, number> {
  const term = word.normalize('NFKC').toLocaleLowerCase('en-US');
  const read = (candidate: string) => {
    const letter = /^[a-z]$/.test(candidate[0] ?? '') ? candidate[0] : '0';
    return bucketsByLetter.get(letter)?.[candidate];
  };
  const totals = { noun: 0, verb: 0, adjective: 0, adverb: 0 };
  const merge = (value: number | undefined, allowed?: WordNetPos[]) => {
    if (value === undefined) return;
    const counts = decodePos(value);
    for (const part of parts) if (!allowed || allowed.includes(part)) totals[part] = Math.max(totals[part], counts[part]);
  };
  merge(read(term));
  // Irregulars come from WordNet itself; regular inflections fall back to the stripped lemma,
  // which may only lend the readings its suffix can produce.
  for (const reading of lemmaReadings(term, forms)) merge(read(reading.candidate), reading.allowed);
  return totals;
}

// Returns undefined when no bucket could be loaded, so callers fall back to built-in guesses.
export async function loadWordNetPos(words: readonly string[]): Promise<PosLookup | undefined> {
  const terms = words.map(word => word.normalize('NFKC').toLocaleLowerCase('en-US').replace(/^[^\p{L}\p{N}]+|[^\p{L}\p{N}]+$/gu, '')).filter(Boolean);
  const letters = [...new Set(terms.map(word => /^[a-z]$/.test(word[0]) ? word[0] : '0'))];
  if (!letters.length) return undefined;
  const results = await Promise.allSettled(letters.map(letter => bucket(letter)));
  const loaded = new Map<string, Record<string, number>>();
  results.forEach((result, index) => { if (result.status === 'fulfilled') loaded.set(letters[index], result.value); });
  if (!loaded.size) return undefined;
  let forms: Record<string, string[]> = {};
  // A direct noun entry does not rule out an irregular verb ("sat" -> "sit"). Resolve both,
  // including cross-letter lemmas at punctuation boundaries ("went." -> "go").
  forms = await inflections().catch(() => ({}));
  const extra = new Set<string>();
  for (const word of terms) for (const reading of lemmaReadings(word, forms)) extra.add(/^[a-z]$/.test(reading.candidate[0] ?? '') ? reading.candidate[0] : '0');
  const missing = [...extra].filter(letter => !loaded.has(letter));
  const additional = await Promise.allSettled(missing.map(letter => bucket(letter)));
  additional.forEach((result, index) => { if (result.status === 'fulfilled') loaded.set(missing[index], result.value); });
  return (word: string) => {
    const counts = resolvePos(word, loaded, forms);
    const ordered = parts.filter(part => counts[part] > 0).map(part => [part, counts[part]] as const);
    return ordered.length ? ordered : undefined;
  };
}
